const hosting=document.querySelector?.('meta[name="apex-hosting"]')?.content,staticPreview=hosting==='static',ctf=hosting==='ctf';
let renderer,rendererJob,track=new Track(),circuitReady=false,models=[],garage,audio=new RaceAudio(),sim,state='menu',camera=0,quality=true;
