const cameraNames=['TV POD','COCKPIT','CHASE','TRACKSIDE'],localKey='apex-gp-'+VERSION+'-rounds';
let guestRounds=[];try{const saved=JSON.parse(localStorage.getItem(localKey)||'[]');if(Array.isArray(saved))guestRounds=saved.slice(0,MAX_ROUNDS).filter(r=>r&&typeof r==='object').map((r,i)=>({...r,round:i+1,status:r.status==='started'?'interrupted':r.status,best:Number.isFinite(r.best)&&r.best>0?r.best:null}));}catch{}
