const selectedMode=()=>ctf&&$('mode').value==='qualifying'?'practice':staticPreview&&$('mode').value==='ranked'?'qualifying':$('mode').value;
function refreshCar(){const c=getCar(selectedCar);if(renderer){const i=CARS.indexOf(c);models[i]??=buildCar(renderer,c);}$('teamColor').style.background=c.color;$('selectedName').textContent=c.name;$('selectedModel').textContent=c.model;}
function roundStatus(){const mode=selectedMode(),data=mode==='ranked'?(driverInfo||{attemptsUsed:0,remainingRounds:MAX_ROUNDS,rounds:[],best:null}):null;return mode==='practice'?{attemptsUsed:0,remainingRounds:Infinity,rounds:[],best:null}:data||{attemptsUsed:guestRounds.length,remainingRounds:MAX_ROUNDS-guestRounds.length,rounds:guestRounds,best:Number.isFinite(localBest())?localBest():null};}
