function notify(text,seconds=3){$('message').textContent=text;$('message').classList.add('show');messageTimer=seconds;}
function showError(err){console.error(err);$('errorText').textContent=err.message||String(err);$('errorPanel').hidden=false;}
async function request(path,body,token){if(staticPreview)throw new Error('Ranked timing is unavailable in this preview.');const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'Content-Type':'application/json'}),...(token?{Authorization:'Bearer '+token}:{})},...(body===undefined?{}:{body:JSON.stringify(body),keepalive:true}),signal:AbortSignal.timeout(5000)});let data;try{data=await response.json();}catch{throw new Error('Timing service returned an invalid response.');}if(!response.ok)throw new Error(data.error||'Timing service unavailable.');return data;}
async function loadBoard(){if(staticPreview)return;try{const data=await request('/api/leaderboard');entries=data.entries;$('boardStatus').textContent='SERVER-VERIFIED · BEST OF THREE ROUNDS';}catch{$('boardStatus').textContent=ctf?'Event timing is offline. Practice is available.':'Event timing is offline. Local qualifying is available.';}renderBoard();}
function renderBoard(){$('eventBoard').innerHTML=entries.map(e=>`<div class="board-row"><span><small>${String(e.rank).padStart(2,'0')}</small>${escapeHTML(e.team)}</span><span>${formatTime(e.time)}</span><b>${e.points}</b></div>`).join('')||'<div class="empty-board">No ranked times yet.</div>';}
async function refreshDriver(){driverInfo=await request('/api/driver',undefined,ctf?undefined:$('teamToken').value.trim());$('driverDot').classList.add('connected');$('driverStatus').textContent=driverInfo.team+' · '+driverInfo.remainingRounds+' of 3 rounds remaining. Your best time is retained.';if(ctf){$('rctfSignIn').hidden=true;$('rctfSignOut').hidden=false;}refreshRounds();}
