  let registration=null;const mode=selectedMode();practice=mode==='practice';ranked=mode==='ranked';
  if(ranked){if(ctf?!driverInfo:!$('teamToken').value.trim()){$('settingsDialog').showModal();throw new Error(ctf?'Sign in with rCTF in Driver settings.':'Enter your team token in Driver settings.');}registration=await request('/api/session',{car:selectedCar,tyre:selectedTyre},ctf?undefined:$('teamToken').value.trim());if(registration.version!==VERSION)throw new Error('The event changed. Reload before qualifying.');driverInfo={...driverInfo,...registration};currentRound=registration.round;}
  else if(!practice){if(guestRounds.length>=MAX_ROUNDS)throw new Error('All three qualifying rounds are complete. Your best time is retained.');currentRound=guestRounds.length+1;guestRounds.push({round:currentRound,car:selectedCar,tyre:selectedTyre,status:'started',best:null});saveGuest();}else currentRound=0;
  stream=registration?{...registration,pending:[],sequence:0,sending:false,final:false,ended:false,failed:false,official:null}:null;
  sim=new Qualifying(track,{car:selectedCar,tyre:selectedTyre,seed:registration?.seed??2026,singleLap:!practice});notice='';state='driving';camera=0;clearInput();camEye=null;camTarget=null;accumulator=0;last=performance.now();audio.start();
  $('paddock').hidden=true;$('menuShade').hidden=true;$('raceUI').hidden=false;$('pausePanel').hidden=true;$('pause').hidden=false;$('errorPanel').hidden=true;document.body.classList.add('racing');$('runMode').textContent=practice?'PRACTICE':ranked?'EVENT QUALIFYING':'QUALIFYING';$('roundBadge').innerHTML=practice?'FP <small>OPEN</small>':'Q'+currentRound+' <small>/ 3</small>';$('connection').textContent=ranked?'LIVE VALIDATION':'LOCAL · UNRANKED';$('raceControls').classList.remove('faded');
