 const keys=DRIVING_KEYS;addEventListener('keydown',e=>{if($('controlsDialog').open||$('timingDialog').open||$('settingsDialog').open||/INPUT|SELECT/.test(document.activeElement?.tagName))return;if(ranked&&!e.isTrusted)return;if(state==='driving'&&keys[e.code]){e.preventDefault();input[keys[e.code]]=true;}if(e.repeat)return;if(e.code==='KeyM')toggleSound();if(e.code==='Escape'){e.preventDefault();state==='paused'?resume():pause();}if(state!=='driving')return;if(e.code==='KeyE')input.up=true;if(e.code==='KeyQ')input.down=true;if(e.code==='KeyC'){camera=(camera+1)%cameraNames.length;camEye=null;camTarget=null;}if(e.code==='KeyR'&&practice){sim.resetCar();clearInput();camEye=null;camTarget=null;notify('CAR RESET · LAP INVALID',3);}});
